UPDATE public.questions SET explanation_data = explanation_data || jsonb_build_object('eg', '"接客ロボットが心から『いらっしゃいませ』と思っていなくても、ちゃんと案内してくれれば十分——これが弱いAIの割り切り。"'::jsonb) WHERE source_ref = 'g-kentei-q3' AND subject_id = (SELECT id FROM public.subjects WHERE slug='g-kentei');
UPDATE public.questions SET explanation_data = explanation_data || jsonb_build_object('eg', '"外国語の教科書の例文をまるごと暗記して答えられても、意味はまるで分かっていないのと同じ。"'::jsonb) WHERE source_ref = 'g-kentei-q4' AND subject_id = (SELECT id FROM public.subjects WHERE slug='g-kentei');
UPDATE public.questions SET explanation_data = explanation_data || jsonb_build_object('eg', '"『出かける前は火の元だけ見ればいい』と割り切れず、『ガス・電気・隣家・天気…』と全部気にして家から出られなくなる人。"'::jsonb) WHERE source_ref = 'g-kentei-q5' AND subject_id = (SELECT id FROM public.subjects WHERE slug='g-kentei');
UPDATE public.questions SET explanation_data = explanation_data || jsonb_build_object('eg', '"『甘い』という字を辞書で覚えても、飴をなめたことがなければ本当の甘さは分からない。言葉と体験がつながっていない状態。"'::jsonb) WHERE source_ref = 'g-kentei-q6' AND subject_id = (SELECT id FROM public.subjects WHERE slug='g-kentei');
UPDATE public.questions SET explanation_data = explanation_data || jsonb_build_object('eg', '"ベテラン店員の接客マニュアルを分厚い一冊にまとめ、新人がその通りに対応する——人の知恵をルール集にした仕組み。"'::jsonb) WHERE source_ref = 'g-kentei-q7' AND subject_id = (SELECT id FROM public.subjects WHERE slug='g-kentei');
UPDATE public.questions SET explanation_data = explanation_data || jsonb_build_object('eg', '"本屋で気になった棚を端から奥までとことん見て、行き止まったら一つ前の棚に戻る探し方。"'::jsonb) WHERE source_ref = 'g-kentei-q8' AND subject_id = (SELECT id FROM public.subjects WHERE slug='g-kentei');
UPDATE public.questions SET explanation_data = explanation_data || jsonb_build_object('eg', '"名人の味を再現しようと『塩少々』の“少々”を数値に書き起こそうとして、どうしても書ききれず手が止まるのと同じ。"'::jsonb) WHERE source_ref = 'g-kentei-q9' AND subject_id = (SELECT id FROM public.subjects WHERE slug='g-kentei');
UPDATE public.questions SET explanation_data = explanation_data || jsonb_build_object('eg', '"『疲れた』と言うと『どうして疲れたの？』とオウム返しする相手。中身は無いのに、なぜか話を聞いてもらえた気になる。"'::jsonb) WHERE source_ref = 'g-kentei-q10' AND subject_id = (SELECT id FROM public.subjects WHERE slug='g-kentei');
UPDATE public.questions SET explanation_data = explanation_data || jsonb_build_object('eg', '"答えの無いおもちゃ箱を『似た形ごと』に自分で仕分けるのが教師なし。『これは車・これは電車』と教わって当てるのが教師あり。"'::jsonb) WHERE source_ref = 'g-kentei-q11' AND subject_id = (SELECT id FROM public.subjects WHERE slug='g-kentei');
UPDATE public.questions SET explanation_data = explanation_data || jsonb_build_object('eg', '"たい焼きに鯛が入っていないように、名前（回帰）と中身（分類）は一致しない。名前に惑わされない。"'::jsonb) WHERE source_ref = 'g-kentei-q12' AND subject_id = (SELECT id FROM public.subjects WHERE slug='g-kentei');
UPDATE public.questions SET explanation_data = explanation_data || jsonb_build_object('eg', '"k-meansは名簿なしでクラスを『仲良しグループ』に分ける先生。k-NNは転校生が周りの席の子に聞いて『何組っぽい？』と当てる方法。"'::jsonb) WHERE source_ref = 'g-kentei-q13' AND subject_id = (SELECT id FROM public.subjects WHERE slug='g-kentei');
