UPDATE public.questions SET explanation_data = explanation_data || jsonb_build_object('eg', '"過去問の答えだけ丸暗記した受験生。同じ問題なら満点でも、初見の問題でつまずく。"'::jsonb) WHERE source_ref = 'g-kentei-q15' AND subject_id = (SELECT id FROM public.subjects WHERE slug='g-kentei');
UPDATE public.questions SET explanation_data = explanation_data || jsonb_build_object('eg', '"5人で持ち回りの当番。全員が一度は当番（テスト役）を経験するよう回して、平均で評価する。"'::jsonb) WHERE source_ref = 'g-kentei-q16' AND subject_id = (SELECT id FROM public.subjects WHERE slug='g-kentei');
UPDATE public.questions SET explanation_data = explanation_data || jsonb_build_object('eg', '"間違えた問題だけを次の人がやり直すリレー勉強。前の失点を後ろが取り返して、チーム全体が賢くなる。"'::jsonb) WHERE source_ref = 'g-kentei-q17' AND subject_id = (SELECT id FROM public.subjects WHERE slug='g-kentei');
UPDATE public.questions SET explanation_data = explanation_data || jsonb_build_object('eg', '"伝言ゲームで、後ろに伝わるほど声が小さくなり、最後の人には何も聞こえない。手前の層に学習の“声”が届かない。"'::jsonb) WHERE source_ref = 'g-kentei-q18' AND subject_id = (SELECT id FROM public.subjects WHERE slug='g-kentei');
