UPDATE public.questions SET explanation_data = explanation_data || jsonb_build_object('eg', '"メモ帳を持った伝言役。大事なことはメモ（記憶）に残し、要らない話は消しながら進むので、長い話でも要点を忘れない。"'::jsonb) WHERE source_ref = 'g-kentei-q26' AND subject_id = (SELECT id FROM public.subjects WHERE slug='g-kentei');
