UPDATE public.questions SET explanation_data = explanation_data || jsonb_build_object('eg', '"RNNは窓口ひとつに一人ずつ順番待ち。Transformerは全員分の窓口を開けて一斉にさばくので速い。"'::jsonb) WHERE source_ref = 'g-kentei-q28' AND subject_id = (SELECT id FROM public.subjects WHERE slug='g-kentei');
