UPDATE public.questions SET explanation_data = explanation_data || jsonb_build_object('eg', '"自転車に乗れる人はバイクの習得も速い。すでに持つ知識を活かすのが転移学習、その上で微調整するのがファインチューニング。"'::jsonb) WHERE source_ref = 'g-kentei-q36' AND subject_id = (SELECT id FROM public.subjects WHERE slug='g-kentei');
